	return fmt.Sprintf("%s(axis=%v, operands=[#%s])",
		ni.Type(),
		ni.Axis,
		strings.Join(xslices.Map(ni.Operands, func(node *NodeImpl) string { return fmt.Sprintf("#%d", node.Id()) }), ", "),
	)
