// CloneWithInputs implements the interface NodeInputs.
func (ni *NodeInputsConcatenate) CloneWithInputs(originalNode *NodeImpl, newInputs ...*NodeImpl) *NodeImpl {
	// Reconstruct inputs from newInputs
	idx := 0
	new_operands := newInputs[idx : idx+len(ni.Operands)]
	idx += len(ni.Operands)
	return BackendConcatenate(ni.Axis, new_operands...)
}

// BackendConcatenate is an internal GraphImpl wrapper for the compute.Function.Concatenate method.
func BackendConcatenate(axis int, operands ...*NodeImpl) (
	node *NodeImpl) {
	inputNodes := []*NodeImpl{}
	inputNodes = append(inputNodes, operands...)
	g := ValidateBuildingGraphFromInputs(inputNodes...)
	inputs := &NodeInputsConcatenate{
		Axis:     axis,
		Operands: slices.Clone(operands),
	}
	result, err := g.currentFunc.backendFunc.Concatenate(inputs.Axis, xslices.Map(operands, func(node *NodeImpl) compute.Value { return node.outputOps[0] })...)
	if err != nil {
		panic(err)
	}
	node = &NodeImpl{
		outputOps:    []compute.Value{result},
		outputShapes: []shapes.Shape{mustNoError(g.builder.OpShape(result))},
		graph:        g,
		inputs:       inputs,
		inputNodes:   inputNodes,
	}
	g.registerNode(node)
	return
}

