// NodeInputsDynamicSlice holds the inputs used for the call to compute.DynamicSlice.
type NodeInputsDynamicSlice struct {
	Operand      *NodeImpl
	StartIndices []*NodeImpl
	SliceDims    []int
}

// Type implements the interface NodeInputs.
func (ni *NodeInputsDynamicSlice) Type() NodeType {
	return NodeTypeDynamicSlice
}

// String implements the interface NodeInputs.
func (ni *NodeInputsDynamicSlice) String() string {
	return fmt.Sprintf("%s(operand=[#%d], startIndices=[#%s], sliceDims=%v)",
		ni.Type(),
		ni.Operand.Id(),
		strings.Join(xslices.Map(ni.StartIndices, func(node *NodeImpl) string { return fmt.Sprintf("#%d", node.Id()) }), ", "),
		ni.SliceDims,
	)
}

// CloneWithInputs implements the interface NodeInputs.
func (ni *NodeInputsDynamicSlice) CloneWithInputs(originalNode *NodeImpl, newInputs ...*NodeImpl) *NodeImpl {
	// Reconstruct inputs from newInputs
	idx := 0
	new_operand := newInputs[idx]
	idx++
	new_startIndices := newInputs[idx : idx+len(ni.StartIndices)]
	idx += len(ni.StartIndices)
	return DynamicSlice(new_operand, new_startIndices, ni.SliceDims)
}

// DynamicSlice extracts a slice from the operand at the startIndices position and the given sliceSizes.
//
// - operand: tensor from where to take the slice.
// - startIndices: scalar tensors, one per axis of operand: len(startIndices) == operand.Rank().
// - sliceSizes: static values and fixed to keep the shape of the output static.
//
// The startIndices are adjusted as follows:
//
//	adjustedStartIndices[i] = clamp(0, StartIndices[i], operand.Dimensions[i] - sliceSizes[i])
//
// See description in https://openxla.org/xla/operation_semantics#dynamicslice
func DynamicSlice(operand *NodeImpl, startIndices []*NodeImpl, sliceDims []int) (
	node *NodeImpl) {
	inputNodes := []*NodeImpl{operand}
	inputNodes = append(inputNodes, startIndices...)
	g := ValidateBuildingGraphFromInputs(inputNodes...)
	inputs := &NodeInputsDynamicSlice{
		Operand:      operand,
		StartIndices: slices.Clone(startIndices),
		SliceDims:    slices.Clone(sliceDims),
	}
	result, err := g.currentFunc.backendFunc.DynamicSlice(operand.outputOps[0], xslices.Map(startIndices, func(node *NodeImpl) compute.Value { return node.outputOps[0] }), inputs.SliceDims)
	if err != nil {
		panic(err)
	}
	node = &NodeImpl{
		outputOps:    []compute.Value{result},
		outputShapes: []shapes.Shape{mustNoError(g.builder.OpShape(result))},
		graph:        g,
		inputs:       inputs,
		inputNodes:   inputNodes,
	}
	g.registerNode(node)
	return
}

