// BackendFusedScaledDotProductAttention is an internal GraphImpl wrapper for the compute.Function.FusedScaledDotProductAttention method.
func BackendFusedScaledDotProductAttention(query *NodeImpl, key *NodeImpl, value *NodeImpl, axesLayout compute.AttentionAxesLayout, options *compute.ScaledDotProductAttentionConfig) (
	output *NodeImpl, statesForVJP []*NodeImpl) {
	inputNodes := []*NodeImpl{query, key, value}
	g := ValidateBuildingGraphFromInputs(inputNodes...)
	inputs := &NodeInputsFusedScaledDotProductAttention{
		Query:      query,
		Key:        key,
		Value:      value,
		AxesLayout: axesLayout,
		Options:    options,
	}
	v0, vTrailing, err := g.currentFunc.backendFunc.FusedScaledDotProductAttention(query.outputOps[0], key.outputOps[0], value.outputOps[0], inputs.AxesLayout, inputs.Options)
	if err != nil {
		panic(err)
	}
	outputOps := append([]compute.Value{v0}, vTrailing...)
	node := &NodeImpl{
		outputOps: outputOps,
		outputShapes: xslices.Map(outputOps,
			func(op compute.Value) shapes.Shape { return mustNoError(g.builder.OpShape(op)) }),
		graph:      g,
		inputs:     inputs,
		inputNodes: inputNodes,
	}
	g.registerNode(node)
	splitNodes := SplitNode(node)
	output = splitNodes[0]
	statesForVJP = splitNodes[1:]
	return
}

