// Rem returns the remainder operation, also known as modulo (or Mod for short).
// Notice despite the name XLA implements Mod not IEEE754 Remainder operation.
func Rem(lhs *NodeImpl, rhs *NodeImpl) (
	node *NodeImpl) {
	inputNodes := []*NodeImpl{lhs, rhs}
	g := ValidateBuildingGraphFromInputs(inputNodes...)
	inputs := &NodeInputsRem{
		Lhs: lhs,
		Rhs: rhs,
	}
	result, err := g.currentFunc.backendFunc.Rem(lhs.outputOps[0], rhs.outputOps[0])
	if err != nil {
		panic(err)
	}
	node = &NodeImpl{
		outputOps:    []compute.Value{result},
		outputShapes: []shapes.Shape{mustNoError(g.builder.OpShape(result))},
		graph:        g,
		inputs:       inputs,
		inputNodes:   inputNodes,
	}
	g.registerNode(node)
	return
}

