type NodeInputsSchedulingBarrier struct {
	Operand      *NodeImpl
	Dependencies []*NodeImpl
}

// Type implements the interface NodeInputs.
func (ni *NodeInputsSchedulingBarrier) Type() NodeType {
	return NodeTypeSchedulingBarrier
}

// String implements the interface NodeInputs.
func (ni *NodeInputsSchedulingBarrier) String() string {
	return fmt.Sprintf("%s(operand=[#%d], dependencies=[#%s])",
		ni.Type(),
		ni.Operand.Id(),
		strings.Join(xslices.Map(ni.Dependencies, func(node *NodeImpl) string { return fmt.Sprintf("#%d", node.Id()) }), ", "),
	)
}

// CloneWithInputs implements the interface NodeInputs.
func (ni *NodeInputsSchedulingBarrier) CloneWithInputs(originalNode *NodeImpl, newInputs ...*NodeImpl) *NodeImpl {
	// Reconstruct inputs from newInputs
	idx := 0
	new_operand := newInputs[idx]
	idx++
	new_dependencies := newInputs[idx : idx+len(ni.Dependencies)]
	idx += len(ni.Dependencies)
	return SchedulingBarrier(new_operand, new_dependencies...)
}

// SchedulingBarrier introduces a scheduling barrier.
// Returned value is identity to the operand, but it is guaranteed to depend on all the dependencies.
func SchedulingBarrier(operand *NodeImpl, dependencies ...*NodeImpl) (
	node *NodeImpl) {
	inputNodes := []*NodeImpl{operand}
	inputNodes = append(inputNodes, dependencies...)
	g := ValidateBuildingGraphFromInputs(inputNodes...)
	inputs := &NodeInputsSchedulingBarrier{
		Operand:      operand,
		Dependencies: slices.Clone(dependencies),
	}
	result, err := g.currentFunc.backendFunc.SchedulingBarrier(operand.outputOps[0], xslices.Map(dependencies, func(node *NodeImpl) compute.Value { return node.outputOps[0] })...)
	if err != nil {
		panic(err)
	}
	node = &NodeImpl{
		outputOps:    []compute.Value{result},
		outputShapes: []shapes.Shape{mustNoError(g.builder.OpShape(result))},
		graph:        g,
		inputs:       inputs,
		inputNodes:   inputNodes,
	}
	g.registerNode(node)
	return
}

